mapper.update:
update local_message_outbox
set status = #{exhaustedStatus},
    update_time = now(),
    lease_owner = null,
    lease_until = null,
    next_retry_time = null
where ifnull(retry_count, 0) >= #{maxRetries}
  and (
    status = #{failedStatus}
    or (
      status = #{sendingStatus}
      and (lease_until is null or lease_until <= #{now})
    )
  )

mapper.select:
select * from local_message_outbox
where status = #{status}
order by update_time desc, id desc
limit #{limit}

select * from local_message_outbox
where create_time <= #{beforeTime}
  and ifnull(retry_count, 0) < #{maxRetries}
  and (
    (
      status in (#{pendingStatus}, #{failedStatus})
      and (next_retry_time is null or next_retry_time <= #{now})
    )
    or
    (
      status = #{sendingStatus}
      and (lease_until is null or lease_until <= #{now})
    )
  )
order by id asc
limit #{limit}
